 async function retireExpiredCapturePermissions(){
  const started=performance.now();assert.ok(Number.isFinite(started),'PAGED_AUTHORITY_CAPTURE_CLOCK');const until=started+15000;let previous=started;
  while(true){
   live();assert.equal(s.queueDepth,1,'PAGED_AUTHORITY_CAPTURE_QUEUED');
   for(const [id,c]of s.challenges)if(captureConsentExpired(c)){
    const client=s.clients.get(c.jobId);if(client){await client.close();live();assert.equal(s.queueDepth,1,'PAGED_AUTHORITY_CAPTURE_QUEUED');s.clients.delete(c.jobId);}s.challenges.delete(id);
   }
   for(const [id,c]of s.graphChallenges)if(captureConsentExpired(c,true)){
    if(c.action==='PREPARE_NATIVE_PAGE')await s.nativePreparation.discardReady(c.jobId);
    else if(c.action==='EXECUTE_NATIVE')await s.nativeExecution.discardReady(c.jobId);
    else if(c.action==='READ_ECONOMIC_SETTLEMENT')await s.nativeEconomic.discardReady(c.jobId);
    else if(c.action==='READ_PORTFOLIO')await s.walletPortfolio.discardReady(c.jobId);
    else await s.graphClient.discardReady(c.jobId);
    live();assert.equal(s.queueDepth,1,'PAGED_AUTHORITY_CAPTURE_QUEUED');s.graphChallenges.delete(id);
   }
   if(s.challenges.size===0&&s.graphChallenges.size===0)return;
   const now=performance.now();assert.ok(Number.isFinite(now)&&now>=previous,'PAGED_AUTHORITY_CAPTURE_CLOCK');previous=now;
   assert.ok(now<until,'PAGED_AUTHORITY_CAPTURE_PERMISSION_TIMEOUT');
   await new Promise(resolve=>setTimeout(resolve,Math.min(100,until-now)));
  }
 }
